/**
 * Nội dung trang Tra cứu. Mỗi mục là một function hay một từ khóa SQL.
 * Ví dụ của nhóm `create` và `dml` là một đoạn nhiều lệnh ngăn bằng dấu `;`, lệnh cuối cho thấy kết quả.
 * Nhóm `create` chạy trên database trống. Mọi nhóm khác chạy trên database tiệm trà sữa.
 */
export type RefGroup = 'string' | 'number' | 'date' | 'null' | 'cast' | 'agg' | 'filter' | 'join' | 'sub' | 'create' | 'dml';

export const refGroups: { id: RefGroup; label: string }[] = [
  { id: 'string', label: 'Chuỗi' },
  { id: 'number', label: 'Số' },
  { id: 'date', label: 'Ngày giờ' },
  { id: 'null', label: 'NULL và rẽ nhánh' },
  { id: 'cast', label: 'Đổi data type' },
  { id: 'agg', label: 'Gom nhóm' },
  { id: 'filter', label: 'Lọc và sắp xếp' },
  { id: 'join', label: 'Nối table' },
  { id: 'sub', label: 'Subquery và ghép kết quả' },
  { id: 'create', label: 'Tạo và sửa table' },
  { id: 'dml', label: 'Sửa dữ liệu' },
];

export interface RefForm {
  syntax: string;
  example: string;
}

export interface RefEntry {
  id: string;
  group: RefGroup;
  /** Tên chính, ví dụ `LENGTH`. Hai dialect gọi khác nhau thì viết cả hai: `IFNULL, NVL`. */
  title: string;
  /** Từ để tìm: tên ở dialect kia và cụm tiếng Việt không dấu. */
  keys: string[];
  /** Một câu nói nó dùng để làm gì. */
  what: string;
  mysql?: RefForm;
  oracle?: RefForm;
  /** Chỗ hai dialect khác nhau, hoặc thứ tương đương khi dialect thiếu. */
  note?: string;
  /** Id bài học dạy nó. */
  lesson?: string;
}

